mapper.select:
SELECT EXISTS(SELECT 1 FROM pf.workspace_environment e JOIN pf.workspace_environment_operation o ON o.id=e.operation_id
    WHERE e.space_id=#{spaceId} AND e.workspace_id=#{workspaceId}
        AND(e.pending_operation_id IS NOT NULL OR(o.protocol='ENVIRONMENT_V3' AND e.state IN('PREPARING','STOPPING','DELETING'))))
